package org.emransm.moviebox.phone;

import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;
import org.json.JSONObject;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;

/** System-managed single-file downloads; fresh-source retry metadata never contains a source address. */
public final class PhoneDownloads {
 private static final String PREFS="phone_downloads";
 private static final Map<Activity,Set<Dialog>> OPEN=new WeakHashMap<>();
 private static void show(Activity a,AlertDialog dialog){Set<Dialog> ownedDialogs=OPEN.get(a);if(ownedDialogs==null){ownedDialogs=new HashSet<>();OPEN.put(a,ownedDialogs);}ownedDialogs.add(dialog);dialog.setOnDismissListener(value->{Set<Dialog> owned=OPEN.get(a);if(owned!=null){owned.remove(dialog);if(owned.isEmpty())OPEN.remove(a);}});dialog.show();}
 public static void close(Activity a){Set<Dialog> owned=OPEN.remove(a);if(owned!=null)for(Dialog dialog:new ArrayList<>(owned))dialog.dismiss();}
 public interface Playback {void open(Uri uri,String title);}
 public interface Retry {void resolve(JSONObject subject,int season,int episode,int quality);}
 interface Backend {long enqueue(Request request)throws Exception;Snapshot query(long id)throws Exception;Uri file(long id)throws Exception;void remove(long id)throws Exception;}
 interface Store {Map<String,?> all();void put(String id,String record);void remove(String id);}
 static final class Request {final String source,title,name,mime;final boolean metered;final int networkTypes;Request(String source,String title,String name,String mime,boolean metered){this.source=source;this.title=title;this.name=name;this.mime=mime;this.metered=metered;this.networkTypes=DownloadPolicy.allowedNetworkTypes(metered);}}
 static final class Snapshot {final int state,reason;final long downloaded,total;Snapshot(int state,int reason,long downloaded,long total){this.state=state;this.reason=reason;this.downloaded=downloaded;this.total=total;}}
 private PhoneDownloads(){}
 private static Backend backend(Activity activity){Context context=activity.getApplicationContext();DownloadManager manager=(DownloadManager)context.getSystemService(Context.DOWNLOAD_SERVICE);return new Backend(){
  public long enqueue(Request value){DownloadManager.Request request=new DownloadManager.Request(Uri.parse(value.source)).addRequestHeader("User-Agent",Api.UA).setTitle(value.title).setDescription("MovieBox download").setMimeType(value.mime).setAllowedOverMetered(value.metered).setAllowedNetworkTypes(value.networkTypes).setAllowedOverRoaming(false).setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setDestinationInExternalFilesDir(context,Environment.DIRECTORY_MOVIES,value.name);return manager.enqueue(request);}
  public Snapshot query(long id){try(Cursor c=manager.query(new DownloadManager.Query().setFilterById(id))){if(c!=null&&c.moveToFirst())return new Snapshot(c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS)),c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_REASON)),c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR)),c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES)));return new Snapshot(0,0,0,0);}}
  public Uri file(long id){return manager.getUriForDownloadedFile(id);}public void remove(long id){manager.remove(id);}
 };}
 private static Store store(Activity activity){SharedPreferences prefs=activity.getSharedPreferences(PREFS,Context.MODE_PRIVATE);return new Store(){public Map<String,?> all(){return prefs.getAll();}public void put(String id,String record){if(!prefs.edit().putString(id,record).commit())throw new IllegalStateException("Download record could not be saved");}public void remove(String id){prefs.edit().remove(id).commit();}};}
 static String format(JSONObject source){return DownloadPolicy.extension(source.optString("resourceLink"),source.optString("mimeType",source.optString("contentType")),source.optString("container",source.optString("format",source.optString("extension"))));}
 static JSONObject record(JSONObject subject,int season,int episode,int quality,String title)throws Exception{return new JSONObject().put("title",title).put("subject",new JSONObject().put("subjectId",subject.getString("subjectId")).put("subjectType",subject.optInt("subjectType")).put("title",subject.optString("title"))).put("season",season).put("episode",episode).put("resolution",quality);}
 static JSONObject metadata(Object stored){try{JSONObject value=new JSONObject(String.valueOf(stored));JSONObject subject=value.optJSONObject("subject");if(subject==null||subject.optString("subjectId").isEmpty()||!(subject.optInt("subjectType")==1||subject.optInt("subjectType")==2))return null;return value;}catch(Exception legacy){return null;}}
 static String title(Object stored){JSONObject data=metadata(stored);return data==null?String.valueOf(stored):data.optString("title","MovieBox video");}
 public static void enqueue(Activity activity,JSONObject subject,JSONObject stream,int season,int episode){enqueue(activity,subject,stream,season,episode,null);}
 public static void enqueue(Activity activity,JSONObject subject,JSONObject stream,int season,int episode,Runnable changed){confirm(activity,subject,stream,season,episode,backend(activity),store(activity),changed);}
 static void confirm(Activity a,JSONObject subject,JSONObject stream,int season,int episode,Backend backend,Store store,Runnable changed){
  if(stream.optInt("requireMemberType")>0||stream.optBoolean("vipLocked")||format(stream).isEmpty()){Toast.makeText(a,"This format is not supported for offline downloads. You can still stream it.",Toast.LENGTH_LONG).show();return;}
  CheckBox mobile=new CheckBox(a);mobile.setText("Allow mobile data for this download");mobile.setChecked(false);mobile.setMinHeight(dp(a,48));int padding=dp(a,16);mobile.setPadding(padding,dp(a,8),padding,dp(a,8));String size=stream.optLong("size")>0?"Estimated size: "+android.text.format.Formatter.formatShortFileSize(a,stream.optLong("size"))+".\n":"";
  show(a,new AlertDialog.Builder(a).setTitle("Download video?").setMessage(size+"Wi-Fi only unless you allow mobile data. Roaming is never allowed.").setView(mobile).setNegativeButton("Cancel",null).setPositiveButton("Download",(dialog,which)->enqueueApproved(a,subject,stream,season,episode,mobile.isChecked(),backend,store,changed)).create());
 }
 static void enqueueApproved(Activity a,JSONObject subject,JSONObject stream,int season,int episode,boolean metered,Backend backend,Store store,Runnable changed){
  final JSONObject selected,source;try{selected=new JSONObject(subject.toString());source=new JSONObject(stream.toString());}catch(Exception invalid){return;}
  new Thread(()->{try{
   String extension=format(source);if(extension.isEmpty()||source.optInt("requireMemberType")>0||source.optBoolean("vipLocked"))throw new IllegalArgumentException("This source cannot be downloaded as a single video file.");
   String title=selected.optString("title","MovieBox video")+(season>0?" \u00b7 S"+season+" E"+episode:"");String name=title.replaceAll("[^a-zA-Z0-9._ -]","_");if(name.length()>90)name=name.substring(0,90);name+="-"+System.currentTimeMillis()+extension;
   String mime=extension.equals(".mp4")?"video/mp4":extension.equals(".webm")?"video/webm":"video/x-matroska";String metadata=record(selected,season,episode,source.optInt("resolution"),title).toString();long id=backend.enqueue(new Request(source.optString("resourceLink"),title,name,mime,metered));
   try{store.put(Long.toString(id),metadata);}catch(Exception persist){try{backend.remove(id);}catch(Exception ignored){}throw persist;}a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed()){Toast.makeText(a,metered?"Download queued; mobile data is allowed for this file.":"Download queued on Wi-Fi only. See Downloads for progress.",Toast.LENGTH_LONG).show();if(changed!=null)changed.run();}});
  }catch(Exception error){a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())Toast.makeText(a,"Download could not start. Check storage and connection, then choose the video again.",Toast.LENGTH_LONG).show();});}},"MovieBox-download-queue").start();
 }
 public static View screen(Activity a){return screen(a,null,null);}public static View screen(Activity a,Playback playback){return screen(a,playback,null);}public static View screen(Activity a,Playback playback,Retry retry){return screen(a,playback,retry,backend(a),store(a));}
 static View screen(Activity a,Playback playback,Retry retry,Backend backend,Store store){
  ScrollView scroll=new ScrollView(a);scroll.setFillViewport(true);LinearLayout list=new LinearLayout(a);list.setOrientation(LinearLayout.VERTICAL);int space=dp(a,16);list.setPadding(space,space,space,space);scroll.addView(list);
  Map<String,?> records=store.all();ArrayList<String> ids=new ArrayList<>();for(String key:records.keySet())try{Long.parseLong(key);ids.add(key);}catch(Exception ignored){}Collections.sort(ids,Collections.reverseOrder());
  if(ids.isEmpty()){TextView empty=text(a,"No downloads yet\n\nChoose Download on a title. Supported single-file videos can be saved for offline playback.",16);empty.setGravity(Gravity.CENTER);list.addView(empty,new LinearLayout.LayoutParams(-1,-1));return scroll;}
  TextView note=text(a,"Saved on this phone. New downloads use Wi-Fi unless you allow mobile data.",13);note.setTextColor(0xffadb0b6);list.addView(note);
  Handler ui=new Handler(Looper.getMainLooper());AtomicInteger attachment=new AtomicInteger();final ExecutorService[] worker={null};ArrayList<Row> rows=new ArrayList<>();final Runnable[] tick={null};
  for(String key:ids){Row row=new Row(Long.parseLong(key),key,title(records.get(key)),metadata(records.get(key)));rows.add(row);LinearLayout card=new LinearLayout(a);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(space,dp(a,12),space,dp(a,12));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(a,12);card.setLayoutParams(cp);card.setBackground(shape(a,0xff191a1e));TextView title=text(a,row.title,16);title.setTypeface(null,android.graphics.Typeface.BOLD);card.addView(title);TextView state=text(a,"Checking download\u2026",13);state.setTextColor(0xffadb0b6);card.addView(state);ProgressBar progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff2feda1));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(a,4));pp.topMargin=dp(a,8);pp.bottomMargin=dp(a,12);card.addView(progress,pp);LinearLayout actions=new LinearLayout(a);actions.setGravity(Gravity.CENTER_VERTICAL);card.addView(actions);list.addView(card);
   row.apply=value->{
    row.terminal=DownloadPolicy.terminal(value.state);String label=DownloadPolicy.status(value.state,value.reason);if(value.state==DownloadManager.STATUS_RUNNING)label+=" \u00b7 "+android.text.format.Formatter.formatShortFileSize(a,value.downloaded)+(value.total>0?" / "+android.text.format.Formatter.formatShortFileSize(a,value.total)+" ("+Math.min(100,(int)(value.downloaded*100.0/value.total))+"%)":"");state.setText(label);progress.setIndeterminate(value.total<=0&&value.state==DownloadManager.STATUS_RUNNING);if(value.total>0)progress.setProgress((int)Math.min(100,value.downloaded*100.0/value.total));progress.setVisibility(value.state==DownloadManager.STATUS_RUNNING?View.VISIBLE:View.GONE);
    if(row.previous==value.state)return;row.previous=value.state;actions.removeAllViews();boolean complete=value.state==DownloadManager.STATUS_SUCCESSFUL;
    if(complete){Button play=action(a,"\u25b6  Play",true);play.setOnClickListener(v->{try{Uri uri=backend.file(row.id);if(uri==null)throw new IllegalStateException();if(playback!=null)playback.open(uri,row.title);else a.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"video/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception unavailable){state.setText("Saved file is unavailable. Choose the title to download it again.");actions.removeView(play);}});actions.addView(play);}
    if((value.state==DownloadManager.STATUS_FAILED||value.state==0)&&row.metadata!=null&&retry!=null){Button again=action(a,"Retry",true);again.setOnClickListener(v->{try{retry.resolve(new JSONObject(row.metadata.getJSONObject("subject").toString()),row.metadata.optInt("season"),row.metadata.optInt("episode"),row.metadata.optInt("resolution",720));}catch(Exception failure){Toast.makeText(a,"Open the title and choose Download again.",Toast.LENGTH_LONG).show();}});actions.addView(again);}
    Button remove=action(a,row.terminal?"Remove":"Cancel",false);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-2,dp(a,48));rp.leftMargin=actions.getChildCount()>0?dp(a,12):0;actions.addView(remove,rp);remove.setOnClickListener(v->show(a,new AlertDialog.Builder(a).setTitle(complete?"Remove downloaded video?":row.terminal?"Remove download?":"Cancel download?").setMessage("This removes the entry and any saved or partial file from this phone.").setNegativeButton("Keep",null).setPositiveButton("Remove",(dialog,which)->{ExecutorService active=worker[0];if(active==null||active.isShutdown())return;row.removed=true;remove.setEnabled(false);try{active.execute(()->{try{backend.remove(row.id);store.remove(key);ui.post(()->{rows.remove(row);if(card.getParent()==list)list.removeView(card);if(scroll.isAttachedToWindow()&&store.all().isEmpty())replace(scroll,screen(a,playback,retry,backend,store));});}catch(Exception failed){row.removed=false;ui.post(()->{if(scroll.isAttachedToWindow()){remove.setEnabled(true);Toast.makeText(a,"Could not remove this download. Try again.",Toast.LENGTH_LONG).show();}});}});}catch(RejectedExecutionException detached){row.removed=false;remove.setEnabled(true);}}).create()));
   };
  }
  tick[0]=()->{if(!scroll.isAttachedToWindow())return;ExecutorService executor=worker[0];if(executor==null||executor.isShutdown())return;int epoch=attachment.get();List<Row> active=new ArrayList<>();for(Row row:rows)if(!row.terminal&&!row.removed)active.add(row);if(active.isEmpty())return;try{executor.execute(()->{for(Row row:active){if(Thread.currentThread().isInterrupted())return;Snapshot result;try{result=backend.query(row.id);}catch(Exception failure){result=new Snapshot(-1,0,0,0);}Snapshot value=result;ui.post(()->{if(scroll.isAttachedToWindow()&&attachment.get()==epoch&&!row.removed)row.apply.accept(value);});}ui.post(()->{if(!scroll.isAttachedToWindow()||attachment.get()!=epoch)return;for(Row row:rows)if(!row.terminal&&!row.removed){ui.postDelayed(tick[0],1500);break;}});});}catch(RejectedExecutionException detached){}};
  scroll.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){attachment.incrementAndGet();for(Row row:rows)row.terminal=false;worker[0]=Executors.newSingleThreadExecutor();ui.post(tick[0]);}public void onViewDetachedFromWindow(View v){attachment.incrementAndGet();ui.removeCallbacksAndMessages(null);ExecutorService active=worker[0];worker[0]=null;if(active!=null)active.shutdownNow();}});return scroll;
 }
 interface Applied {void accept(Snapshot snapshot);}static final class Row {final long id;final String key,title;final JSONObject metadata;boolean terminal;volatile boolean removed;int previous=-1;Applied apply;Row(long id,String key,String title,JSONObject metadata){this.id=id;this.key=key;this.title=title;this.metadata=metadata;}}
 private static void replace(View old,View next){if(old.getParent() instanceof ViewGroup){ViewGroup p=(ViewGroup)old.getParent();int i=p.indexOfChild(old);ViewGroup.LayoutParams lp=old.getLayoutParams();p.removeView(old);p.addView(next,i,lp);}}
 private static int dp(Activity a,int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}private static android.graphics.drawable.GradientDrawable shape(Activity a,int color){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(a,12));d.setStroke(dp(a,1),0xff303238);return d;}
 private static Button action(Activity a,String value,boolean primary){Button b=new Button(a);b.setText(value);b.setTextSize(14);b.setAllCaps(false);b.setMinHeight(dp(a,48));b.setPadding(dp(a,16),0,dp(a,16),0);b.setTextColor(primary?0xff101114:0xffc8ccd1);b.setBackground(shape(a,primary?0xff2feda1:0xff191a1e));b.setContentDescription(value);return b;}private static TextView text(Activity a,String value,int size){TextView t=new TextView(a);t.setText(value);t.setTextColor(Color.rgb(240,241,243));t.setTextSize(size);t.setPadding(0,dp(a,4),0,dp(a,4));return t;}
}
